# Generated by manage.py generate_test_cases.
from django.http import HttpResponse

from bloomerp.filters.definition import FilterCondition
from bloomerp.models.project_management.todo_label import TodoLabel
from bloomerp.permissions.definition import BloomerpPermission, RowPolicyRuleContent
from bloomerp.permissions.manager import PolicyManager
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestAssistantObjectRetrieveView(BloomerpAPIViewTestCase):
    """Tests class `AssistantObjectRetrieveView` from `bloomerp/views/api/mutations.py`."""

    view_name = 'api_assistant_object_retrieve'

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover artifact retrieval, row denial, and unknown generated models."""
        return [
            RequestScenario(
                name="Retrieves current permitted fields from an object artifact",
                description=(
                    "UC: An agent reads a known object using its artifact identity.\n"
                    "Expected Result: Current readable fields and the mutation resource "
                    "are returned without exposing denied fields."
                ),
                user=self.normal_user,
                prepare=self.prepare_readable_object,
                expected=ExpectedResult(response_validators=self.object_was_retrieved),
            ),
            RequestScenario(
                name="An artifact identity does not bypass row permissions",
                description=(
                    "UC: An agent supplies the ID of an object outside the user's row grant.\n"
                    "Expected Result: The endpoint returns 404 without revealing the object."
                ),
                user=self.normal_user,
                prepare=self.prepare_hidden_object,
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Rejects an unknown generated API model",
                description=(
                    "UC: An agent supplies a model label absent from the generated API.\n"
                    "Expected Result: The endpoint returns a model-label validation error."
                ),
                user=self.admin_user,
                query_params={"model_label": "bloomerp.UnknownModel", "object_id": "42"},
                expected=ExpectedResult(
                    status_code=400,
                    response_validators=self.json_exact(
                        {"model_label": "Unknown generated API model."}
                    ),
                ),
            ),
        ]

    def prepare_readable_object(self, scenario: RequestScenario) -> None:
        """Create an artifact target with a row grant and a restricted field set."""
        self.label = TodoLabel.objects.create(name="Current name", color="#123456")
        policy = PolicyManager.create_policy(
            model_or_content_type=TodoLabel,
            field_permissions={
                "id": [BloomerpPermission.VIEW],
                "name": [BloomerpPermission.VIEW],
            },
            row_permissions=[
                RowPolicyRuleContent(
                    permissions=[BloomerpPermission.VIEW],
                    conditions=[
                        FilterCondition(
                            field_path="id", lookup_id="equals", value=str(self.label.pk)
                        )
                    ],
                )
            ],
        )
        PolicyManager.assign(policy, self.normal_user)
        scenario.query_params = {
            "model_label": TodoLabel._meta.label,
            "object_id": str(self.label.pk),
        }

    def prepare_hidden_object(self, scenario: RequestScenario) -> None:
        """Point the artifact at a row outside an otherwise valid read policy."""
        self.prepare_readable_object(scenario)
        hidden_label = TodoLabel.objects.create(name="Hidden", color="#654321")
        scenario.query_params["object_id"] = str(hidden_label.pk)

    def object_was_retrieved(self, response: HttpResponse) -> bool:
        """Verify the artifact identity, mutation resource, and exact readable fields."""
        return response.json() == {
            "resource": "todo_labels",
            "model_label": TodoLabel._meta.label,
            "object_id": str(self.label.pk),
            "object": {"id": str(self.label.pk), "name": "Current name"},
        }
